import{_ as o,o as t,c as d,a3 as a}from"./chunks/framework.BlfGB29P.js";const q=JSON.parse('{"title":"Tenant API v1 — Quotations","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Quotations | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-quotations"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Quotations | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-quotations"}]]},"headers":[],"relativePath":"api/tenant-v1-quotations.md","filePath":"api/tenant-v1-quotations.md","lastUpdated":1787335124000}'),i={name:"api/tenant-v1-quotations.md"};function n(c,e,s,r,u,l){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-v1-—-quotations" tabindex="-1">Tenant API v1 — Quotations <a class="header-anchor" href="#tenant-api-v1-—-quotations" aria-label="Permalink to &quot;Tenant API v1 — Quotations&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:quotations</code>, plus permission middleware / policies.</p><p>Assignee scoping: without <code>quotations.assign</code> (and not superadmin), list/stats/view/update/<strong>send</strong>/<strong>accept</strong>/<strong>convert</strong> only include quotations where <code>assigned_to</code> is the current user.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-quotations-stats" tabindex="-1">GET <code>/quotations/stats</code> <a class="header-anchor" href="#get-quotations-stats" aria-label="Permalink to &quot;GET `/quotations/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort).</p><h2 id="quotations-crud" tabindex="-1">Quotations CRUD <a class="header-anchor" href="#quotations-crud" aria-label="Permalink to &quot;Quotations CRUD&quot;">​</a></h2><h3 id="get-quotations" tabindex="-1">GET <code>/quotations</code> <a class="header-anchor" href="#get-quotations" aria-label="Permalink to &quot;GET `/quotations`&quot;">​</a></h3><p>Query: <code>search</code>, <code>status</code>, <code>opportunity_id</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_quotations</code>, <code>trashed</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>status</code>, <code>opportunity</code>, assignee/creator refs, <code>subtotal</code>/<code>discount_total</code>/<code>tax_total</code>/<code>total</code>, <code>converted_invoice</code> ref (<code>number</code>/<code>status</code>) when present, and <code>latest_note</code>.</p><h3 id="post-quotations" tabindex="-1">POST <code>/quotations</code> <a class="header-anchor" href="#post-quotations" aria-label="Permalink to &quot;POST `/quotations`&quot;">​</a></h3><p>Body: <code>opportunity_id</code> (required), <code>contact_id</code>, <code>company_id</code> (optional, module-entitlement + assignee-scope validated), <code>title</code> (required), <code>notes</code> (HTML memo, sanitized server-side), <code>terms_and_conditions</code> (HTML, sanitized server-side), <code>currency</code> (3-letter, default <code>USD</code>), <code>valid_until</code> (date), <code>assigned_to</code>, <code>line_discount_type</code> (<code>none</code>|<code>percent</code>|<code>fixed</code>), <code>lines</code> (array of <code>{ product_id?, name, body?, quantity, unit_price, tax_rate, sort_order, discount_value }</code>). <code>product_id</code> is optional and requires the Products module, <code>products.view</code> (or superadmin), and an active non-trashed product (<code>LinkableProduct</code>). <code>body</code> is optional HTML line details. <code>discount_value</code> is required on a line when <code>line_discount_type</code> is not <code>none</code>. The server stores client-sent <code>name</code>/<code>body</code>/<code>unit_price</code> as-is (does not re-copy from the product catalog).</p><p><code>subtotal</code>, <code>discount_total</code>, <code>tax_total</code>, and <code>total</code> are computed server-side from <code>lines</code> and <code>line_discount_type</code> — do not send them. Tax is calculated after line discounts. <code>discount_total</code> is the sum of line discounts only.</p><h3 id="get-quotations-id" tabindex="-1">GET <code>/quotations/{id}</code> <a class="header-anchor" href="#get-quotations-id" aria-label="Permalink to &quot;GET `/quotations/{id}`&quot;">​</a></h3><p>Includes opportunity, assignee, creator, lines (<code>product_id</code>, optional <code>product</code> <code>{id,sku,name}</code> when loaded, <code>name</code>, <code>body</code>, <code>discount_value</code>), document <code>line_discount_type</code> / <code>discount_total</code>, <code>notes</code>, <code>terms_and_conditions</code>, <code>converted_invoice</code> when present, and timeline activities. Embedded <code>notes</code> and timeline/domain <code>activities</code> are <strong>newest-first</strong> (<code>created_at</code> DESC, then <code>id</code> DESC).</p><h3 id="get-quotations-id-pdf" tabindex="-1">GET <code>/quotations/{id}/pdf</code> <a class="header-anchor" href="#get-quotations-id-pdf" aria-label="Permalink to &quot;GET `/quotations/{id}/pdf`&quot;">​</a></h3><p>Permission: <code>quotations.view</code> (assignee-scoped). Extra limiter <code>throttle:quotations-pdf</code>. Returns <code>application/pdf</code> attachment. Branded layout matches invoices (logo, button color, company profile). Includes sanitized memo HTML, line items, and discount/tax/total breakdown.</p><h3 id="put-quotations-id" tabindex="-1">PUT <code>/quotations/{id}</code> <a class="header-anchor" href="#put-quotations-id" aria-label="Permalink to &quot;PUT `/quotations/{id}`&quot;">​</a></h3><p>Partial update of <strong>draft</strong> quotations only. Sending <code>lines</code> replaces the full line-item set and recalculates totals (including <code>line_discount_type</code> and per-line <code>discount_value</code>). Non-draft quotations return 422 on <code>status</code> (<code>Only draft quotations can be edited.</code>). Assignment after send uses <code>POST /quotations/{id}/assign</code>.</p><h3 id="delete-quotations-id" tabindex="-1">DELETE <code>/quotations/{id}</code> <a class="header-anchor" href="#delete-quotations-id" aria-label="Permalink to &quot;DELETE `/quotations/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>quotations.delete</code>.</p><h3 id="post-quotations-id-restore" tabindex="-1">POST <code>/quotations/{id}/restore</code> <a class="header-anchor" href="#post-quotations-id-restore" aria-label="Permalink to &quot;POST `/quotations/{id}/restore`&quot;">​</a></h3><p>Permission: <code>quotations.restore</code>.</p><h3 id="delete-quotations-id-force" tabindex="-1">DELETE <code>/quotations/{id}/force</code> <a class="header-anchor" href="#delete-quotations-id-force" aria-label="Permalink to &quot;DELETE `/quotations/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted quotation. Permission: <code>quotations.force.delete</code>.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-quotations-id-assign" tabindex="-1">POST <code>/quotations/{id}/assign</code> <a class="header-anchor" href="#post-quotations-id-assign" aria-label="Permalink to &quot;POST `/quotations/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><p>Permission: <code>quotations.assign</code>.</p><h3 id="post-quotations-id-send" tabindex="-1">POST <code>/quotations/{id}/send</code> <a class="header-anchor" href="#post-quotations-id-send" aria-label="Permalink to &quot;POST `/quotations/{id}/send`&quot;">​</a></h3><p>Transitions <code>draft → sent</code>. Permission: <code>quotations.send</code> (assignee-scoped unless the actor has <code>quotations.assign</code> or is superadmin). <strong>Status-only</strong> — does not email or generate a PDF.</p><h3 id="post-quotations-id-accept" tabindex="-1">POST <code>/quotations/{id}/accept</code> <a class="header-anchor" href="#post-quotations-id-accept" aria-label="Permalink to &quot;POST `/quotations/{id}/accept`&quot;">​</a></h3><p>Transitions <code>sent → accepted</code>. Permission: <code>quotations.accept</code> (assignee-scoped unless the actor has <code>quotations.assign</code> or is superadmin).</p><h3 id="post-quotations-id-convert" tabindex="-1">POST <code>/quotations/{id}/convert</code> <a class="header-anchor" href="#post-quotations-id-convert" aria-label="Permalink to &quot;POST `/quotations/{id}/convert`&quot;">​</a></h3><p>Converts a <strong>sent</strong> or <strong>accepted</strong> quotation into a <strong>draft</strong> <code>CustomerInvoice</code>:</p><ul><li>Requires the <strong>Invoices</strong> module to be entitled (soft, call-time check — no <code>module_dependencies</code> row). Returns 422 if Invoices is not installed.</li><li>Creates the invoice with the quotation&#39;s <code>title</code>, <code>notes</code>, <code>terms_and_conditions</code>, <code>currency</code>, <code>line_discount_type</code>, <code>contact_id</code>, <code>company_id</code>, <code>assigned_to</code>, and a copy of every line item</li><li>Sets <code>customer_invoices.quotation_id</code> on the new invoice</li><li>Transitions the quotation to <code>accepted</code> if it wasn&#39;t already</li><li>Records a <code>converted</code> activity on the quotation</li></ul><p>Permission: <code>quotations.convert</code> (assignee-scoped unless the actor has <code>quotations.assign</code> or is superadmin). Rejects with a 422 if the quotation is not sent/accepted, or if any invoice (including soft-deleted) already has this <code>quotation_id</code> — one-shot, including invoices created from a linked estimate or contract. Soft-deleted invoices still block convert; the error message tells operators to restore or permanently delete the invoice. Concurrent converts are serialized with <code>lockForUpdate</code> on the quotation row. Returns the created <strong>invoice</strong> (<code>CustomerInvoiceResource</code>), not a quotation, with HTTP 201.</p><h3 id="post-quotations-id-status" tabindex="-1">POST <code>/quotations/{id}/status</code> <a class="header-anchor" href="#post-quotations-id-status" aria-label="Permalink to &quot;POST `/quotations/{id}/status`&quot;">​</a></h3><p><code>{ &quot;status&quot;: &quot;draft&quot;|&quot;sent&quot;|&quot;accepted&quot;|&quot;rejected&quot;|&quot;expired&quot; }</code></p><p>Authorization depends on the target status:</p><ul><li><code>sent</code> → <code>quotations.send</code></li><li><code>accepted</code> → <code>quotations.accept</code></li><li>other allowed transitions (e.g. <code>rejected</code>, <code>expired</code>) → <code>quotations.update</code></li></ul><p>Rejects disallowed transitions (including re-sending an already-<code>sent</code> quotation) with a 422 validation error on <code>status</code>. Records a <code>status_changed</code> timeline entry.</p><h3 id="post-quotations-id-notes" tabindex="-1">POST <code>/quotations/{id}/notes</code> <a class="header-anchor" href="#post-quotations-id-notes" aria-label="Permalink to &quot;POST `/quotations/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><p>Permission: <code>quotations.update</code>.</p><h3 id="get-quotations-id-timeline" tabindex="-1">GET <code>/quotations/{id}/timeline</code> <a class="header-anchor" href="#get-quotations-id-timeline" aria-label="Permalink to &quot;GET `/quotations/{id}/timeline`&quot;">​</a></h3><p>Domain timeline entries (<code>created</code>, <code>updated</code>, <code>assigned</code>, <code>status_changed</code>, <code>converted</code>, <code>note_added</code>, <code>deleted</code>, <code>restored</code>).</p>',48)])])}const h=o(i,[["render",n]]);export{q as __pageData,h as default};
